package com.innovatus.studentrecords.service; import java.security.SecureRandom; import java.time.*; public class OTPService {private String otp;private Instant expiry; public String create(){otp="%06d".formatted(new SecureRandom().nextInt(1_000_000));expiry=Instant.now().plusSeconds(300);return otp;} public boolean verify(String value){return otp!=null&&Instant.now().isBefore(expiry)&&otp.equals(value);}}
